    cout << idx + 1 << " ] " << fixed << setprecision(2) << val << endl;
}

int main() {
    random_device rd;
    default_random_engine engine(rd());
    uniform_real_distribution<double> dist(10.0, 20.0);

    int smartSize = getArraySize("스마트포인터");
    unique_ptr<double[]> smartArr = make_unique<double[]>(smartSize);

    for (int i = 0; i < smartSize; ++i) {
        smartArr[i] = dist(engine);
        printElement(i, smartArr[i]);
    }

    int newSize = getArraySize("new 연산자");
    double* rawArr = new double[newSize];

    for (int i = 0; i < newSize; ++i) {
        rawArr[i] = dist(engine);
        printElement(i, rawArr[i]);
    }

    delete[] rawArr;
    rawArr = nullptr;

    cout << endl;
    return 0;
}

