void change_pointer(int **pp, int *target) { *pp = target; }
int main() {
    int a = 1, b = 2;
    int *p = &a;
    change_pointer(&p, &b);
    printf("%d\n", *p);
    return 0;
}

def create_profile(name, age, **kwargs):
    print(f"{name} {age}")
    for k in sorted(kwargs):
        print(f"{k}={kwargs[k]}")

create_profile("민수", 20, city="서울", job="학생")

#include <iostream>
using namespace std;

int main() {
    int size;
    std::cout << "배열의 크기를 입력하세요: ";
    std::cin >> size;
    std::cout << size <<std::endl;

    // C++ 스타일 동적 할당
    int* arr = new int[size];

    std::cout << size << "개의 정수를 입력하세요: ";
    int sum = 0;
    for (int i = 0; i < size; i++) {
        std::cin >> arr[i];
        std::cout << arr[i] << " ";
        sum += arr[i];
    }

    std::cout << "\n입력한 정수의 합계: " << sum << std::endl;

    // C++ 스타일 동적 배열 해제
    delete[] arr;
    arr = nullptr; // 안전한 포인터 초기화

    return 0;
}

class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author

    def info(self):
        print(f"제목: {self.title}, 저자: {self.author}")


b1 = Book("파이썬 기초", "홍길동")
b1.info()
